const customer = $('Get many Customers').first().json.display_name;
const setItems = $input.all();
const parser = $('Quotation / Expiration Date Parser + unit price Null remover').first().json;
const parserProducts = parser.products || [];

// Build product list with optional fields
const list = setItems.map(it => {
  const productName = it.json.display_name || "";
  const productNameLower = productName.toLowerCase();

  // Match by name
  const match = parserProducts.find(p => {
    const name = (p.product_name || "").toLowerCase();
    return productNameLower.includes(name) || name.includes(productNameLower);
  });

  let details = `${productName}`;
  if (match) {
    const parts = [];
    if (match.quantity) parts.push(`x${match.quantity}`);
    if (match.unit_price) parts.push(`${match.unit_price} DT/unit`);
    if (match.taxes && match.taxes.length > 0) parts.push(`taxes: ${match.taxes.join(", ")}`);
    if (parts.length > 0) details += ` (${parts.join(", ")})`;
  }
  return details;
}).join(", ");

// Build optional extra info
const extras = [];
if (parser.payment_terms) extras.push(`Payment Terms: ${parser.payment_terms}`);
if (parser.quotation_date) extras.push(`Quotation Date: ${parser.quotation_date}`);
if (parser.expiration_date) extras.push(`Expiration Date: ${parser.expiration_date}`);
const extrasText = extras.length > 0 ? ` | ${extras.join(" | ")}` : "";

return {
  reply: `Sales order created successfully for ${customer} with ${list}.${extrasText}`
};

return {
  reply: "The customer name you provided  does not exist in Odoo. Please check the name or create the customer before making a sales order."
};

