// --- Handle Expiration Date ---
let expirationDate = output.expiration_date 
  ? new Date(output.expiration_date) 
  : new Date(quotationDate);

if (!output.expiration_date) {
  expirationDate.setMonth(expirationDate.getMonth() + 1);
}

const formattedExpiration = `${expirationDate.getFullYear()}-${pad(expirationDate.getMonth()+1)}-${pad(expirationDate.getDate())} ${pad(expirationDate.getHours())}:${pad(expirationDate.getMinutes())}:${pad(expirationDate.getSeconds())}`;

// --- Validation ---
let reply = null;

if (quotationDate > new Date()) {
  reply = "Error: Quotation date cannot be in the future.";
}

if (expirationDate <= quotationDate) {
  reply = "Error: Expiration date must be after quotation date.";
}

