const orderId = $items("Create a sales order")[0].json.id;
const parserItems = $items("Quotation / Expiration Date Parser + unit price Null remover")[0].json.products || [];

// Collect all tax records from the Get Many Taxes node
const allTaxes = $items("Get Many Taxes").map(i => i.json);

// Map each product item from Get Many Products
return $items("Get many Products").map(item => {
  const productName = (item.json.name || "").toLowerCase().trim();
  const match = parserItems.find(p => (p.product_name || "").toLowerCase().trim() === productName);

  let tax_ids = null;
  if (match && Array.isArray(match.taxes)) {
    const taxIds = match.taxes.map(taxName => {
      // Compare against Odoo tax names (case-insensitive)
      const found = allTaxes.find(t => (t.name || "").toLowerCase() === taxName.toLowerCase());
      return found ? found.id : null;
    }).filter(id => id !== null);

    if (taxIds.length > 0) {
      tax_ids = [[6, 0, taxIds]];
    }
  }

  return {
    json: {
      order_id: orderId,
      product_id: item.json.id,
      product_name: item.json.name || null,   // ✅ added product name
      product_uom_qty: match ? match.quantity : null,
      price_unit: match ? match.unit_price : null,
      tax_ids
    }
  };
});

