const updatedProducts = $('AI Agent4').first().json.output.updated_products || [];
const products = $('Get many Products3').all().map(i => i.json);
const orderLines = $('Get many sales order lines1').all().map(i => i.json);
const taxes = $('Get Many Taxes3').all().map(i => i.json); // {id, name}

// Helper: find product id by name
function findProductId(name) {
  const match = products.find(p => p.name === name);
  return match ? match.id : null;
}

// Helper: find sales order line by product id or name
function findOrderLine(productId, productName) {
  return orderLines.find(l => {
    if (Array.isArray(l.product_id)) {
      return l.product_id[0] === productId || l.product_id[1] === productName;
    }
    return l.product_id === productId;
  }) || null;
}

// Helper: resolve tax IDs by names
function findTaxIds(taxNames) {
  if (!taxNames) return null;
  const ids = taxNames.map(name => {
    const match = taxes.find(t => t.name === name);
    return match ? match.id : null;
  }).filter(id => id !== null);
  return ids.length > 0 ? ids : null;
}

const result = updatedProducts.map(up => {
  const existingProductId = findProductId(up.existing_product_name);
  const newProductId = up.new_product_name ? findProductId(up.new_product_name) : null;
  const orderLine = existingProductId ? findOrderLine(existingProductId, up.existing_product_name) : null;

  // Fallbacks: if AI agent didn’t provide values, use order line values
  const finalProductId = newProductId || (orderLine ? orderLine.product_id[0] : null);
  const finalQuantity = up.new_quantity !== null && up.new_quantity !== undefined
    ? up.new_quantity
    : (orderLine ? orderLine.product_uom_qty : null);
  const finalUnitPrice = up.new_unit_price !== null && up.new_unit_price !== undefined
    ? up.new_unit_price
    : (orderLine ? orderLine.price_unit : null);
  const finalTaxIds = up.new_taxes
    ? findTaxIds(up.new_taxes)
    : (orderLine ? orderLine.tax_ids : null);

  return {
    json: {
      existing_product_name: up.existing_product_name,
      existing_product_id: existingProductId,
      sales_order_line_id: orderLine ? orderLine.id : null,
      new_product_name: up.new_product_name || (orderLine ? orderLine.product_id[1] : null),
      new_product_id: finalProductId,
      new_quantity: finalQuantity,
      new_unit_price: finalUnitPrice,
      new_taxes: up.new_taxes || null,   // names from AI Agent if provided
      new_tax_ids: finalTaxIds           // resolved IDs or fallback from order line
    }
  };
});

return result;

