  replyParts.push(`Order ${agentOutput.existing_order_name}`);
} else if (agentOutput.existing_customer_name) {
  replyParts.push(`Customer ${agentOutput.existing_customer_name}`);
}
if (agentOutput.existing_order_date) {
  replyParts.push(`(Date: ${agentOutput.existing_order_date})`);
